        savePlayerStats:function(){
            if(this.storage == null) return;
			
			this.storage.set('levelStats', this.lockLevel);
			this.storage.set('movementStats', this.movementCount);
        },

        getPlayerStats:function(){
			if(this.storage == null) return;
			
			var lockTheLevel = this.storage.get('levelStats');
			if(lockTheLevel!=null)this.lockLevel = lockTheLevel;
			
			var cekMovement = this.storage.get('movementStats');
			if(cekMovement != null)this.movementCount = cekMovement;
		},
		
		startGame:function(){	
			this.resetPlayerStats();
								
			// TEST Eg: load level using Director plugin
			if(ig.ua.mobile){
				this.director = new ig.Director(this,[
						LevelOpening,
						LevelGameplay,
						LevelLevelEasy
				]);										
			}else{
				this.director = new ig.Director(this,[
						LevelOpening,
						LevelGameplay,
						LevelLevelEasy
				]);					
			}
			
			// CALL LOAD LEVELS
			if(_SETTINGS['Branding']['Splash']['Enabled']){
				try{
					this.branding = new ig.BrandingSplash();
				}catch(err){
					console.log(err)
					console.log('Loading original levels ...')
					this.director.loadLevel(this.director.currentLevel);
				}					
			}else{
				this.director.loadLevel(this.director.currentLevel);
			}
						
			//this.spawnEntity(EntityPointer,50,50);
						
			// MUSIC // Changed to use ig.soundHandler
			//ig.soundHandler.playBackgroundMusic();	
			if(ig.ua.mobile){
				if(this.music){
					ig.soundHandler.playBackgroundMusic();
				} else {
					ig.soundHandler.playBackgroundMusic();
					ig.soundHandler.setForceMutedBgm(true);
					ig.soundHandler._muteBackgroundMusic();
				}
				if(this.sound){
					//ig.soundHandler._unMuteSounds();
                    ig.soundHandler.setForceMutedSfx(false);
                    ig.soundHandler._unMuteSounds();
				} else {
					ig.soundHandler.setForceMutedSfx(true);
					ig.soundHandler._muteSounds();
				}
			}else{
				if(this.music){
					ig.soundHandler.playBackgroundMusic();						
				} else {
					ig.soundHandler.setForceMutedBgm(true);
					ig.soundHandler._muteBackgroundMusic();
				}
				if(this.sound){
					ig.soundHandler.setForceMutedSfx(false);
					ig.soundHandler._unMuteSounds();
				} else {
					ig.soundHandler.setForceMutedSfx(true);
					ig.soundHandler._muteSounds();
				}
			}
		},
		
