		fpsCount: function(){
			if(!this.fpsTimer){
				this.fpsTimer = new ig.Timer(1);
			}
			if(this.fpsTimer && this.fpsTimer.delta() < 0){
				if(this.fpsCounter != null){
					this.fpsCounter ++ ;
				}else{
					this.fpsCounter = 0 ;
				}
			}else{
				ig.game.fps = this.fpsCounter ;
				this.fpsCounter = 0 ;
				this.fpsTimer.reset();
			}
		},	
			
